function ocanDb(?string$name=null):mysqli{$db=new mysqli(getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1',getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root',getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local',$name,(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306));$db->set_charset('utf8mb4');return$db;}
$token=bin2hex(random_bytes(5));$database='t_ocan_'.$token;$admin=ocanDb();$db=null;
try{
 $admin->query("CREATE DATABASE `{$database}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=ocanDb($database);$db->query("CREATE TABLE fm2_pilot_users(user_id BIGINT PRIMARY KEY,full_name VARCHAR(300) NULL,email VARCHAR(254) NULL,status TINYINT NOT NULL,activation_state VARCHAR(20) NOT NULL)");$db->query("INSERT INTO fm2_pilot_users VALUES(41,'Исторический <Автор>','old@example.test',0,'blocked'),(42,'','fallback@example.test',1,'active')");
 $card=['id'=>4512,'address'=>'Адрес','entrance'=>'1','registrationNumber'=>'REG','plannedStartDate'=>null,'plannedFinishDate'=>null,'status'=>'Требуется распоряжение','order'=>null,'controlEngineer'=>null,'opened'=>false,'actualStartDate'=>null,'actualStartDateUnknownAtCutover'=>false,'openedAt'=>null,'openedByUserId'=>null,'activeCaseProvenance'=>null,'dataOrigin'=>'native','events'=>[['type'=>'event-one','occurredAt'=>'2026-09-01T10:00:00+03:00','actorId'=>41],['type'=>'event-two','occurredAt'=>'2026-09-01T11:00:00+03:00','actorId'=>42],['type'=>'event-three','occurredAt'=>'2026-09-01T12:00:00+03:00','actorId'=>43]],'hasPtoAct'=>false];
 $previous=new class($card)implements ObjectCardReader{public function __construct(private array$card){}public function read(int$id):?array{return$id===4512?$this->card:null;}};
 $reader=new MariaDbAppliedObjectCardReader($db,'legacy_','',$previous);$result=$reader->read(4512);assertSameValue([41,42,43],array_column($result['events'],'actorId'),'immutable event actor IDs preserved');assertSameValue(['Исторический <Автор>','fallback@example.test',null],array_column($result['events'],'actorName'),'one batch local-user projection includes inactive name, email fallback and absent user');
 $html=(new ProductionObjectCardRenderer())->render(new HttpUser(999,'Текущий пользователь','viewer@example.test',['objects.read']),$result);assertSameValue(true,str_contains($html,'Исторический &lt;Автор&gt;'),'historical inactive actor name is escaped');assertSameValue(false,str_contains($html,'Исторический <Автор>'),'historical actor name cannot inject HTML');assertSameValue(true,str_contains($html,'fallback@example.test'),'blank local name falls back to stored email');assertSameValue(true,str_contains($html,'Пользователь недоступен · ID 43'),'absent local user has truthful ID fallback');assertSameValue(false,str_contains($html,'Пользователь 41'),'legacy numeric label removed');assertSameValue(1,substr_count($html,'Текущий пользователь'),'viewer identity remains only in its own shell');echo"PASS object card resolves immutable historical actor names\n";
}finally{if($db instanceof mysqli)$db->close();$admin->query("DROP DATABASE IF EXISTS `{$database}`");$admin->close();}

