gnmentOrderOriginal\AssignmentOrderOriginalMode::CORRECTION,4512,81,18,'2026-09-03',true,$accepted->rootOriginalId(),$accepted->currentRevisionId(),$accepted->currentRevisionId(),'Исправлена дата',new FMonitor2\AssignmentOrderOriginal\AssignmentOrderOriginalUpload(new FMonitor2\AssignmentOrderOriginal\AssignmentOrderOriginalMemoryStream(FMonitor2\Tests\Support\SelectedOriginalFixture::pdf()),'signed.pdf','application/pdf')));assertSameValue('accepted',$corrected->status()->value,'corrected original before opening');$correctedCard=$reader->read(4512);assertSameValue([1,null,null,null],[(int)$nativeDb->query('SELECT COUNT(*) n FROM fm2_assignment_order_applications')->fetch_assoc()['n'],$correctedCard['actualStartDate'],$correctedCard['openedAt'],$correctedCard['openedByUserId']],'correction read preserves old application and unopened case');assertSameValue([(string)$corrected->currentRevisionId(),1,'confirmed'],[$correctedCard['confirmedOriginal']['revisionId'],$correctedCard['confirmedOriginal']['sequence'],$correctedCard['order']['status']],'unopened card binds corrected current original with existing sequence');echo"PASS accepted original returns to truthful unapplied card\n";
